INSERT INTO `posts` VALUES (1,'1','2','Admin Broadcast','Dear CHAPTER II Members,\r\nA quick reminder for our Weekly EAF Connect Meeting 🤝\r\n\r\n📅 Date: 02nd April 2026\r\n⏰ Time: 7:00 AM to 9:30 AM\r\n📍 Venue: Terige Bhavana, Naagarbhaavi, Bangalore.\r\n\r\nLet’s build strong connections, exchange quality referrals, plan F2Fs and create more business opportunities 🚀\r\nLet’s make this meeting impactful!\r\n\r\n– Team EAF Connect','1775029753_b56229d14e399f5c780b.jpeg','1','1','2026-04-01 07:49:13'),(2,'2','2','New Meeting Invitation','📅 Meeting Scheduled: Chapter Meeting on Apr 09, 2026 07:00 AM - Dear CHAPTER II Members,\r\nA quick reminder for our Weekly EAF Connect Meeting 🤝\r\n\r\n📅 Date: 9th April 2026\r\n⏰ Time: 7:00 AM to 9:30 AM\r\n📍 Venue: Terige Bhavana, Naagarbhaavi, Bangalore.\r\n\r\nLet’s build strong connections, exchange quality referrals, plan F2Fs and create more business opportunities 🚀\r\nLet’s make this meeting impactful!\r\n\r\n– Team EAF Connect',NULL,'1','12','2026-04-02 10:53:19'),(3,'3','2','Important Announcement','You’re Invited!  \r\nEntrepreneurs Awareness Forum (EAF) – Chapter II  \r\nStronger the Network, Higher the Net-worth! Join us to meet the right people & grow your business   \r\n\r\nDate: Thursday, 23rd April 2026\r\n  Time: 7:00 AM – 9:30 AM\r\n\r\n  Venue: Terige Bhavana, 11th Block, 2nd Stage, Nagarabhavi  \r\nEntry: FREE A great opportunity to connect, collaborate & expand your network \r\n\r\nFor more information: +91 9008887037 \r\nDon’t miss it – Meet | Greet | Network','1776865535_3bea0ca5b7151534912e.jpeg','1','1','2026-04-22 19:15:35'),(4,'4','2','New Meeting Invitation','📅 Meeting Scheduled: Chapter Meeting on 06 Aug, 2026 04:00 PM - Good Evening members.. \r\n\r\nA gentle reminder before tomorrow&#039;s meeting:\r\n\r\n✅ Please record all your Connects and Money in the Bank (MIB) in the EAF Connect appication before the meeting.\r\n\r\n🎤 Come well prepared with your presentation and be ready to make the most of your networking opportunity.\r\n\r\nLet&#039;s bring great energy, meaningful connections, and valuable business opportunities to the meeting.\r\n\r\nLooking forward to seeing you all tomorrow. Let&#039;s make it a fantastic meeting\r\n\r\n\r\n\r\nWith Gratitude \r\nTEAM LT',NULL,'1','5','2026-08-05 17:57:01'),(5,'5','2','New Meeting Invitation','📅 Meeting Scheduled: Chapter Meeting on 06 Aug, 2026 04:00 PM - Good Evening members.. \r\n\r\nA gentle reminder before tomorrow&#039;s meeting:\r\n\r\n✅ Please record all your Connects and Money in the Bank (MIB) in the EAF Connect appication before the meeting.\r\n\r\n🎤 Come well prepared with your presentation and be ready to make the most of your networking opportunity.\r\n\r\nLet&#039;s bring great energy, meaningful connections, and valuable business opportunities to the meeting.\r\n\r\nLooking forward to seeing you all tomorrow. Let&#039;s make it a fantastic meeting\r\n\r\n\r\n\r\nWith Gratitude \r\nTEAM LT',NULL,'1','5','2026-08-05 17:58:02'),(6,'6','2','New Meeting Invitation','📅 Meeting Scheduled: Chapter Meeting on 06 Aug, 2026 04:00 PM - Good Evening members.. \r\n\r\nA gentle reminder before tomorrow&#039;s meeting:\r\n\r\n✅ Please record all your Connects and Money in the Bank (MIB) in the EAF Connect appication before the meeting.\r\n\r\n🎤 Come well prepared with your presentation and be ready to make the most of your networking opportunity.\r\n\r\nLet&#039;s bring great energy, meaningful connections, and valuable business opportunities to the meeting.\r\n\r\nLooking forward to seeing you all tomorrow. Let&#039;s make it a fantastic meeting\r\n\r\n\r\n\r\nWith Gratitude \r\nTEAM LT',NULL,'1','5','2026-08-05 18:01:43'),(7,'7','2','New Meeting Invitation','📅 Meeting Scheduled: Chapter Meeting on 06 Aug, 2026 04:00 PM - Good Evening members.. \r\n\r\nA gentle reminder before tomorrow&#039;s meeting:\r\n\r\n✅ Please record all your Connects and Money in the Bank (MIB) in the EAF Connect appication before the meeting.\r\n\r\n🎤 Come well prepared with your presentation and be ready to make the most of your networking opportunity.\r\n\r\nLet&#039;s bring great energy, meaningful connections, and valuable business opportunities to the meeting.\r\n\r\nLooking forward to seeing you all tomorrow. Let&#039;s make it a fantastic meeting\r\n\r\n\r\n\r\nWith Gratitude \r\nTEAM LT',NULL,'1','5','2026-08-05 18:02:43'),(8,'8','2','New Meeting Invitation','📅 Meeting Scheduled: Chapter Meeting on 13 Aug, 2026 08:00 AM - ## **🌸 WOMEN ENTREPRENEURS DAY 🌸**\r\n\r\n**Connect • Collaborate • Grow**\r\n\r\nJoin entrepreneurs, professionals, and business leaders for a powerful networking session.\r\n\r\n📅 **13th August 2026 (Thursday)**\r\n🕢 **7:00 AM** – Open Networking\r\n🕢 **7:30 AM** – Meeting Starts\r\n📍 **Terige Bhavan, Nagarbhavi, Bengaluru**\r\n\r\n🎟️ **FREE Entry | Breakfast Included**\r\n\r\n### **Why Attend?**\r\n\r\n🤝 Expand Your Network\r\n💼 Generate Business Opportunities\r\n💡 Exchange Ideas\r\n🚀 Build Lasting Business Connections\r\n\r\n📞 **RSVP:** **93418 73532**\r\n\r\n**Meet • Connect • Grow Together!**\r\n',NULL,'1','5','2026-08-07 17:37:44'),(9,'9','2','New Meeting Invitation','📅 Meeting Scheduled: Chapter Meeting on 13 Aug, 2026 08:00 AM - ## **🌸 WOMEN ENTREPRENEURS DAY 🌸**\r\n\r\n**Connect • Collaborate • Grow**\r\n\r\nJoin entrepreneurs, professionals, and business leaders for a powerful networking session.\r\n\r\n📅 **13th August 2026 (Thursday)**\r\n🕢 **7:00 AM** – Open Networking\r\n🕢 **7:30 AM** – Meeting Starts\r\n📍 **Terige Bhavan, Nagarbhavi, Bengaluru**\r\n\r\n🎟️ **FREE Entry | Breakfast Included**\r\n\r\n### **Why Attend?**\r\n\r\n🤝 Expand Your Network\r\n💼 Generate Business Opportunities\r\n💡 Exchange Ideas\r\n🚀 Build Lasting Business Connections\r\n\r\n📞 **RSVP:** **93418 73532**\r\n\r\n**Meet • Connect • Grow Together!**\r\n',NULL,'1','5','2026-08-07 17:38:44');
