DROP TABLE IF EXISTS `users`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `users` (
  `user_id` int(11) NOT NULL AUTO_INCREMENT,
  `user_code` varchar(50) NOT NULL,
  `name` varchar(255) NOT NULL,
  `last_name` varchar(50) NOT NULL,
  `email` varchar(255) NOT NULL,
  `password` varchar(255) NOT NULL,
  `phone` varchar(20) NOT NULL,
  `alt_phone` varchar(20) NOT NULL,
  `whatsapp` varchar(20) NOT NULL,
  `address` varchar(100) NOT NULL,
  `city` varchar(100) NOT NULL,
  `state` varchar(100) NOT NULL,
  `country` varchar(100) NOT NULL,
  `pincode` varchar(10) NOT NULL,
  `referred_by` varchar(50) NOT NULL,
  `profile_photo` varchar(300) NOT NULL DEFAULT 'empty.png',
  `gender` varchar(200) NOT NULL,
  `dob` varchar(100) NOT NULL,
  `designation` varchar(300) NOT NULL,
  `exp_years` varchar(200) NOT NULL,
  `skills` varchar(300) NOT NULL,
  `services` text NOT NULL,
  `products` text NOT NULL,
  `bio` text NOT NULL,
  `collab_interests` varchar(300) NOT NULL,
  `referral_prefs` varchar(300) NOT NULL,
  `website` varchar(200) NOT NULL,
  `linkedin` varchar(300) NOT NULL,
  `facebook` varchar(300) NOT NULL,
  `instagram` varchar(300) NOT NULL,
  `twitter` varchar(200) NOT NULL,
  `youtube` varchar(200) NOT NULL,
  `google_business` varchar(300) NOT NULL,
  `awards` varchar(300) NOT NULL,
  `certifications` varchar(300) NOT NULL,
  `languages` varchar(200) NOT NULL,
  `hobbies` varchar(300) NOT NULL,
  `tags` varchar(400) NOT NULL,
  `business_logo` varchar(300) NOT NULL,
  `business_card` varchar(300) NOT NULL,
  `brochure` varchar(200) NOT NULL,
  `portfolio` varchar(300) NOT NULL,
  `role` enum('admin','member') NOT NULL DEFAULT 'member',
  `status` enum('1','2','3') NOT NULL DEFAULT '1',
  `verified` enum('1','2','3') NOT NULL DEFAULT '1',
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `renewal_date` date DEFAULT '2027-04-01',
  `member_role` enum('President','Vice President','Secretary Treasurer','Chapter Growth','Member') NOT NULL DEFAULT 'Member',
  `member_type` enum('member','gold_member') NOT NULL DEFAULT 'member',
  `join_date` date DEFAULT NULL,
  `token` varchar(300) NOT NULL,
  `last_active` varchar(100) NOT NULL,
  `business_name` varchar(200) NOT NULL,
  `industry` varchar(300) NOT NULL,
  `subcategory` varchar(200) NOT NULL,
  `description` varchar(300) NOT NULL,
  `reg_number` varchar(200) NOT NULL,
  `gst_number` varchar(50) NOT NULL,
  `start_year` varchar(100) NOT NULL,
  `employees` varchar(200) NOT NULL,
  `office_address` varchar(200) NOT NULL,
  `working_hours` varchar(100) NOT NULL,
  `service_areas` varchar(300) NOT NULL,
  `refferd_by` varchar(200) NOT NULL,
  `refferd_by_name` varchar(200) NOT NULL,
  PRIMARY KEY (`user_id`),
  UNIQUE KEY `email` (`email`)
) ENGINE=InnoDB AUTO_INCREMENT=97 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

